# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        span = Span(9 * 60 + 5, 17 * 60 + 10)
        self.assertEqual(
            round_spans([span], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        span = Span(9 * 60 + 15, 10 * 60 + 45)
        self.assertEqual(
            round_spans([span], 30),
            ["09:30-11:00 (1h 30m)"]
        )

    def test_several_spans(self):
        spans = [Span(60, 120), Span(125, 185)]
        self.assertEqual(
            round_spans(spans, 10),
            ["01:00-02:00 (1h 0m)", "02:10-03:10 (1h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 90):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)

    def test_span_that_vanishes_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(61, 64)], 15)

if __name__ == "__main__":
    unittest.main()
